package com.citacloud.springboot.contacloud.app.repositories;
import com.citacloud.springboot.contacloud.app.models.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;
public interface VentaGuardadaRepository extends JpaRepository<VentaGuardada,UUID>{
 @Query(value="select v from VentaGuardada v where v.tenantId=:tenant and v.empresaId=:empresa and v.sucursalId=:sucursal and (v.estado=com.citacloud.springboot.contacloud.app.models.EstadoVentaGuardada.SAVED or (v.estado=com.citacloud.springboot.contacloud.app.models.EstadoVentaGuardada.IN_USE and v.recuperadaPor=:usuario and v.terminalRecuperacionId=:terminal)) and (:otros=true or v.creadaPor=:usuario) and (:q='' or lower(v.numero) like concat('%',:q,'%') or lower(coalesce(v.referencia,'')) like concat('%',:q,'%') or lower(v.clienteNombre) like concat('%',:q,'%')) order by case when lower(v.numero)=:q then 0 else 1 end,v.actualizadaEn desc,v.id desc",countQuery="select count(v) from VentaGuardada v where v.tenantId=:tenant and v.empresaId=:empresa and v.sucursalId=:sucursal and (v.estado=com.citacloud.springboot.contacloud.app.models.EstadoVentaGuardada.SAVED or (v.estado=com.citacloud.springboot.contacloud.app.models.EstadoVentaGuardada.IN_USE and v.recuperadaPor=:usuario and v.terminalRecuperacionId=:terminal)) and (:otros=true or v.creadaPor=:usuario) and (:q='' or lower(v.numero) like concat('%',:q,'%') or lower(coalesce(v.referencia,'')) like concat('%',:q,'%') or lower(v.clienteNombre) like concat('%',:q,'%'))")
 Page<VentaGuardada> buscar(@Param("tenant")UUID tenant,@Param("empresa")UUID empresa,@Param("sucursal")UUID sucursal,@Param("usuario")UUID usuario,@Param("terminal")UUID terminal,@Param("otros")boolean otros,@Param("q")String q,Pageable pageable);
 @Query("select count(v) from VentaGuardada v where v.tenantId=:tenant and v.empresaId=:empresa and v.sucursalId=:sucursal and (v.estado=com.citacloud.springboot.contacloud.app.models.EstadoVentaGuardada.SAVED or (v.estado=com.citacloud.springboot.contacloud.app.models.EstadoVentaGuardada.IN_USE and v.recuperadaPor=:usuario and v.terminalRecuperacionId=:terminal)) and (:otros=true or v.creadaPor=:usuario)")
 long contar(@Param("tenant")UUID tenant,@Param("empresa")UUID empresa,@Param("sucursal")UUID sucursal,@Param("usuario")UUID usuario,@Param("terminal")UUID terminal,@Param("otros")boolean otros);
 Optional<VentaGuardada> findByIdAndTenantIdAndEmpresaId(UUID id,UUID tenant,UUID empresa);
 @Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE)@Query("select v from VentaGuardada v where v.id=:id and v.tenantId=:tenant and v.empresaId=:empresa")
 Optional<VentaGuardada> bloquear(@Param("id")UUID id,@Param("tenant")UUID tenant,@Param("empresa")UUID empresa);
}
